package com.asmj.marketplace.security; import jakarta.servlet.*; import jakarta.servlet.http.*; import lombok.RequiredArgsConstructor; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.security.core.userdetails.UserDetails; import org.springframework.stereotype.Component; import org.springframework.web.filter.OncePerRequestFilter; @Component @RequiredArgsConstructor public class JwtAuthenticationFilter extends OncePerRequestFilter {private final JwtService jwt; private final CustomUserDetailsService users; protected void doFilterInternal(HttpServletRequest r,HttpServletResponse s,FilterChain f)throws ServletException,java.io.IOException{String h=r.getHeader("Authorization"); if(h!=null&&h.startsWith("Bearer ")){String t=h.substring(7);try{if(jwt.valid(t)&&SecurityContextHolder.getContext().getAuthentication()==null){UserDetails u=users.loadUserByUsername(jwt.email(t));SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(u,null,u.getAuthorities()));}}catch(Exception ignored){}} f.doFilter(r,s);}}
